import sys

try:
    from defusedxml import minidom
except ImportError:  # pragma: no cover - fallback only if dependency absent
    from xml.dom import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
# CT_RPr children that must follow w:u in schema order
AFTER_U = {"effect", "bdr", "shd", "fitText", "vertAlign", "rtl", "cs",
           "em", "lang", "eastAsianLayout", "specVanish", "oMath"}


def local(el):
    return el.localName or el.tagName.rsplit(":", 1)[-1]


def para_text(p):
    return "".join(t.firstChild.data for t in p.getElementsByTagNameNS(W, "t")
                   if t.firstChild)


def is_headline(p):
    txt = para_text(p).strip()
    if not txt or len(txt) > 80:
        return False
    letters = [c for c in txt if c.isalpha()]
    if not letters:
        return False  # excludes box-drawing divider line
    return all(c.isupper() for c in letters)


def rpr_of(r):
    for ch in r.childNodes:
        if ch.nodeType == ch.ELEMENT_NODE and local(ch) == "rPr":
            return ch
    rpr = r.ownerDocument.createElementNS(W, "w:rPr")
    r.insertBefore(rpr, r.firstChild)
    return rpr


def underline_run(r):
    rpr = rpr_of(r)
    for ch in rpr.childNodes:
        if ch.nodeType == ch.ELEMENT_NODE and local(ch) == "u":
            ch.setAttributeNS(W, "w:val", "single")
            return
    u = rpr.ownerDocument.createElementNS(W, "w:u")
    u.setAttributeNS(W, "w:val", "single")
    anchor = next((ch for ch in rpr.childNodes
                   if ch.nodeType == ch.ELEMENT_NODE and local(ch) in AFTER_U), None)
    if anchor is not None:
        rpr.insertBefore(u, anchor)
    else:
        rpr.appendChild(u)


path = sys.argv[1]
dom = minidom.parse(path)
underlined = []
for p in dom.getElementsByTagNameNS(W, "p"):
    if is_headline(p):
        runs = [r for r in p.getElementsByTagNameNS(W, "r")]
        for r in runs:
            underline_run(r)
        underlined.append(para_text(p).strip())

if not underlined:
    sys.exit("ERROR: no headline paragraphs found; document left unchanged")

with open(path, "w", encoding="utf-8") as fh:
    dom.writexml(fh, addindent="  ", newl="\n", encoding="utf-8")

print("Underlined %d headline paragraph(s):" % len(underlined))
for h in underlined:
    print("  - " + h)

"""Underline all report headlines in unpacked quarterly_report.docx OOXML."""
import io
import sys
from xml.dom import minidom

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'
def q(n):
    return '{%s}%s' % (W, n)

HEADLINES = frozenset([
    'EXECUTIVE SUMMARY',
    'FINANCIAL HIGHLIGHTS',
    'REVENUE BREAKDOWN BY SEGMENT',
    'KEY PERFORMANCE INDICATORS',
    'OPERATING EXPENSES',
    'Q1 2025 OUTLOOK',
    'RISK FACTORS',
])

def para_text(p):
    return ''.join(
        t.firstChild.data
        for t in p.getElementsByTagName(q('t'))
        if t.firstChild and t.firstChild.nodeType == t.TEXT_NODE
    )

def visible_text_run(r):
    return any(
        t.firstChild and t.firstChild.nodeType == t.TEXT_NODE and t.firstChild.data.strip()
        for t in r.getElementsByTagName(q('t'))
    )

path = sys.argv[1]
doc = minidom.parse(path)

underlined = []
u_count = 0

for p in doc.getElementsByTagName(q('p')):
    text = ' '.join(para_text(p).split())
    if text not in HEADLINES:
        continue
    underlined.append(text)
    for r in p.getElementsByTagName(q('r')):
        if not visible_text_run(r):
            continue
        rprs = [c for c in r.childNodes if c.nodeType == c.ELEMENT_NODE and c.tagName == q('rPr')]
        rPr = rprs[0] if rprs else None
        if rPr is None:
            rPr = doc.createElementNS(W, 'w:rPr')
            r.insertBefore(rPr, r.firstChild)
        for old in rPr.getElementsByTagName(q('u')):
            rPr.removeChild(old)
        u = doc.createElementNS(W, 'w:u')
        u.setAttributeNS(W, 'w:val', 'single')
        anchor = None
        for c in rPr.childNodes:
            if c.nodeType == c.ELEMENT_NODE and c.tagName in (
                    q('rFonts'), q('color'), q('sz'), q('sz-cs'), q('highlight')):
                anchor = c
        rPr.insertBefore(u, anchor.nextSibling if anchor is not None else None)
        u_count += 1

buf = io.StringIO()
doc.writexml(buf, encoding='ascii')
with open(path, 'wb') as f:
    f.write(buf.getvalue().encode('ascii', 'xmlcharrefreplace'))

print('Headlines underlined: %d' % len(underlined))
print('Runs marked with w:u single: %d' % u_count)
for h in sorted(underlined):
    print('- %s' % h)
if len(underlined) != len(HEADLINES) or underlined != list(HEADLINES):
    missing = sorted(HEADLINES - set(underlined))
    print('MISSING: %s' % ', '.join(missing) if missing else '')

