"""Underline every headline in the unpacked quarterly report OOXML.

Headlines in this report are paragraphs whose text is fully uppercase
(e.g. "EXECUTIVE SUMMARY", "FINANCIAL HIGHLIGHTS"). Body text, bullet
items, table rows and separator lines contain lowercase letters or no
letters, so they are not affected.
"""
import os
import sys

# Locate the docx skill root so scripts.document is importable.
d = os.path.abspath(".")
while True:
    cand = os.path.join(d, ".codex", "skills", "docx")
    if os.path.isfile(os.path.join(cand, "scripts", "document.py")):
        break
    parent = os.path.dirname(d)
    if parent == d:
        raise SystemExit("Could not locate the docx skill root")
    d = parent
sys.path.insert(0, cand)

from scripts.document import Document  # noqa: E402

WORKSPACE = "quarterly_report_ooxml_workspace"
W_NS_PREFIX = "w"


def paragraph_text(p):
    chunks = []
    for t in p.getElementsByTagName("w:t"):
        if t.firstChild is not None:
            chunks.append(t.firstChild.data)
    return "".join(chunks)


def is_headline(text):
    stripped = text.strip()
    if not stripped:
        return False
    letters = [ch for ch in stripped if ch.isalpha()]
    if not letters:
        return False
    return all(ch.isupper() for ch in letters)


doc = Document(WORKSPACE)
editor = doc["word/document.xml"]
dom = editor.dom

headlines = []
for p in dom.getElementsByTagName("w:p"):
    text = paragraph_text(p)
    if not is_headline(text):
        continue
    headlines.append(text.strip())
    for run in p.getElementsByTagName("w:r"):
        if not (run.getElementsByTagName("w:t") or run.getElementsByTagName("w:delText")):
            continue
        rpr_nodes = run.getElementsByTagName("w:rPr")
        if rpr_nodes:
            rpr = rpr_nodes[0]
        else:
            rpr = dom.createElement(W_NS_PREFIX + ":rPr")
            run.insertBefore(rpr, run.firstChild)
        if not rpr.getElementsByTagName(W_NS_PREFIX + ":u"):
            underline = dom.createElement(W_NS_PREFIX + ":u")
            underline.setAttribute(W_NS_PREFIX + ":val", "single")
            rpr.appendChild(underline)

doc.save()

print("Underlined %d headline(s):" % len(headlines))
for h in headlines:
    print("  - " + h)

